const data = msg.payload;          // объект от inject
const numbers = data.numbers;      // массив чисел

let sum = 0;                       // сумма всех чисел
let evens = [];                    // массив чётных

for (let i = 0; i < numbers.length; i++) {
    sum += numbers[i];
    if (numbers[i] % 2 === 0) {
        evens.push(numbers[i]);
    }
}

const average = sum / numbers.length;

let level;
if (average > 10) {
    level = "high";
} else {
    level = "low";
}

const result = {                   // итоговый объект
    surname: data.surname,
    sum: sum,
    average: average,
    evenNumbers: evens,
    level: level
};

return { payload: result, topic: "lab2/Korostelkina/function" };
